<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Plus, Download, Upload } from '@element-plus/icons-vue'
import { api, download } from '../api'
import { state, refresh, labels, dateText } from '../store'
import FormDialog from '../components/FormDialog.vue'
const tab = ref('users'), data = reactive({ users: [], logs: [], settings: {} }), settings = reactive({}), open = ref(false), kind = ref('user'), initial = ref({}), editId = ref(null), busy = ref(false), restoreFile = ref(null)
async function load() { try { Object.assign(data, await api.get('/system')); Object.assign(settings, data.settings) } catch {} }
onMounted(load)
const fields = computed(() => kind.value === 'user' ? [{ key: 'username', label: '登录账号', tip: '3—30 位字母、数字或下划线' }, { key: 'name', label: '姓名' }, { key: 'password', label: editId.value ? '重置密码（留空不修改）' : '初始密码', type: 'password', required: !editId.value, tip: '至少 8 位' }, { key: 'account_type', label: '账号类型', type: 'select', options: [{ label: '管理员', value: 'ADMIN' }, { label: '业务人员（管理权限）', value: 'STAFF' }, { label: '客户', value: 'CUSTOMER' }] }, { key: 'customer_id', label: '关联客户档案', type: 'select', wide: true, show: form => form.account_type === 'CUSTOMER', options: state.customers.filter(customer => !data.users.some(user => user.customer_id === customer.id && user.id !== editId.value)).map(customer => ({ label: customer.name + ' · ' + customer.phone, value: customer.id })), tip: '新客户请先在客户管理中建档，或使用登录页的客户注册。一个档案仅关联一个账号。' }, { key: 'enabled', label: '账号启用', type: 'switch', required: false }] : [{ key: 'name', label: '门店名称', wide: true }, { key: 'address', label: '门店地址', wide: true }, { key: 'phone', label: '联系电话', wide: true }])
function create(type, row) { kind.value = type; editId.value = row?.id || null; initial.value = row ? { ...row, password: '' } : type === 'user' ? { enabled: true, account_type: 'STAFF' } : {}; open.value = true }
async function save(input) { if (kind.value === 'user') input.role = input.account_type === 'CUSTOMER' ? 'CUSTOMER' : 'ADMIN'; busy.value = true; try { const resource = kind.value === 'user' ? 'users' : 'branches'; await api[editId.value ? 'put' : 'post'](`/system/${resource}` + (editId.value ? '/' + editId.value : ''), input); open.value = false; await Promise.all([load(), refresh()]); ElMessage.success('设置已保存') } catch {} finally { busy.value = false } }
async function saveSettings() { busy.value = true; try { await api.put('/system/settings', settings); await Promise.all([load(), refresh()]); ElMessage.success('系统参数已保存') } catch {} finally { busy.value = false } }
async function backup() { busy.value = true; try { const blob = await api.get('/system/backup', { responseType: 'blob' }); download(blob, '易行租车备份-' + new Date().toISOString().slice(0, 10) + '.zip', 'application/zip'); await load(); ElMessage.success('备份已导出，请妥善保管') } catch {} finally { busy.value = false } }
async function restore(event) {
  const file = event.target.files[0]; event.target.value = ''; if (!file) return
  try {
    await backup()
    const result = await ElMessageBox.prompt('当前数据将被备份内容替换，恢复后需要重新登录。系统已尝试导出当前备份，请确认已保存，再输入 RESTORE 继续。', '恢复数据', { inputPattern: /^RESTORE$/, inputErrorMessage: '请输入 RESTORE', confirmButtonText: '确认恢复', type: 'warning' })
    busy.value = true; const payload = new FormData(); payload.append('file', file); payload.append('confirmation', result.value); await api.post('/system/restore', payload); state.user = null; window.dispatchEvent(new Event('auth:expired')); ElMessage.success('数据已恢复，请重新登录')
  } catch {} finally { busy.value = false }
}
</script>
<template>
  <section class="panel settings-panel"><el-tabs v-model="tab"><el-tab-pane label="账号与权限" name="users"><div class="settings-section-heading"><div><h3>账号管理</h3><p>管理员与业务人员使用相同管理功能，客户仅能访问自己的资料与订单。</p></div><el-button type="primary" :icon="Plus" @click="create('user')">新增账号</el-button></div><el-table :data="data.users"><el-table-column prop="name" label="姓名"/><el-table-column prop="username" label="账号"/><el-table-column label="角色"><template #default="{ row }">{{ labels[row.account_type] || labels[row.role] }}</template></el-table-column><el-table-column label="状态"><template #default="{ row }"><span :class="row.enabled ? 'text-green' : 'text-danger'">{{ row.enabled ? '已启用' : '已禁用' }}</span></template></el-table-column><el-table-column label="操作"><template #default="{ row }"><el-button link type="primary" @click="create('user', row)">编辑 / 重置密码</el-button></template></el-table-column></el-table><div class="permission-note"><h4>权限说明</h4><p><strong>管理员：</strong>全部业务模块、经营报表、账号、门店、计费参数与数据备份恢复。</p><p><strong>业务人员：</strong>与管理员合并为管理角色，拥有完整管理功能。账号类型仅用于区分人员身份。</p><p><strong>客户：</strong>公开注册或由管理员开通；仅可选车预约、查看本人订单、取消未收款预约和更新本人资料。不可访问管理端。</p></div></el-tab-pane><el-tab-pane label="门店管理" name="branches"><div class="settings-section-heading"><div><h3>运营门店</h3><p>车辆所属门店通过调度或实际归还更新。</p></div><el-button type="primary" :icon="Plus" @click="create('branch')">新增门店</el-button></div><el-table :data="state.branches"><el-table-column prop="name" label="门店"/><el-table-column prop="address" label="地址" min-width="240"/><el-table-column prop="phone" label="电话"/><el-table-column label="操作" width="100"><template #default="{ row }"><el-button link type="primary" @click="create('branch', row)">编辑</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="系统参数" name="parameters"><div class="settings-section-heading"><div><h3>基础参数</h3><p>提醒规则任一满足即可触发。</p></div></div><el-form label-position="top" class="settings-form"><el-form-item label="提前保养提醒天数"><el-input-number v-model="settings.reminder_days" :min="0" :max="365"/></el-form-item><el-form-item label="提前保养提醒里程（km）"><el-input-number v-model="settings.reminder_km" :min="0" :max="100000"/></el-form-item><el-button type="primary" :loading="busy" @click="saveSettings">保存参数</el-button></el-form></el-tab-pane><el-tab-pane label="操作日志" name="logs"><div class="settings-section-heading"><div><h3>关键操作记录</h3><p>展示最近 300 条记录，不保存密码和完整证件信息。</p></div><el-button @click="load">刷新日志</el-button></div><el-table :data="data.logs" max-height="540"><el-table-column label="时间" min-width="180"><template #default="{ row }">{{ dateText(row.created_at) }}</template></el-table-column><el-table-column prop="operator" label="操作人" width="120"/><el-table-column prop="action" label="操作" min-width="180"/><el-table-column prop="target" label="对象" min-width="220"/></el-table></el-tab-pane><el-tab-pane label="数据备份与恢复" name="backup"><div class="backup-intro"><h2>保存完整业务快照</h2><p>ZIP 备份包含数据库记录和已上传车辆图片。账号密码以哈希形式保存，但备份仍包含敏感业务资料，请妥善保管，仅导入本系统生成的可信备份。</p></div><div class="backup-grid"><section><el-icon><Download/></el-icon><h3>导出数据备份</h3><p>导出当前账号、车辆、客户、订单、收退款、调度、工单及图片。</p><el-button type="primary" :loading="busy" @click="backup">下载 ZIP 备份</el-button></section><section><el-icon><Upload/></el-icon><h3>恢复可信备份</h3><p>替换当前业务记录。恢复前导出当前数据，二次确认后执行，恢复完成需重新登录。</p><el-button :loading="busy" @click="restoreFile.click()">选择 ZIP 备份</el-button><input ref="restoreFile" type="file" accept=".zip" hidden @change="restore"/></section></div></el-tab-pane></el-tabs></section>
  <FormDialog v-model="open" :title="(editId ? '编辑' : '新增') + (kind === 'user' ? '团队账号' : '门店')" :fields="fields" :initial="initial" :busy="busy" @submit="save"/>
</template>
